use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
    ensures
        // The result is a 2D array with exactly one row
        result.len() == 1,
        // The single row has the same length as the input array
        result[0].len() == arr.len(),
        // For every valid index, the element in the row equals the corresponding input element
        forall|i: int| 0 <= i && i < arr.len() ==> result[0][i] == arr[i],
        // The order is preserved (implied by the element-wise equality)
{
    // Create a new vector with a single element
    let mut result_vec = Vec::new();
    
    // Create a copy of the input array to use as the single row
    let mut row = Vec::new();
    let mut i: usize = 0;
    
    // Copy elements from arr to row
    while i < arr.len() {
        row.push(arr[i]);
        i = i + 1;
    }
    
    // Add the row to the result vector
    result_vec.push(row);
    
    // Return the result
    result_vec
}

} // verus!